# Generated by Claude Opus 5.5 (claude.ai/code) · 2026-11-18
# Pester tests: the CLI itself (src/sequencer.ps1 run in a child pwsh), so argument
# binding and output wiring are covered, not only the library functions.

BeforeAll {
    . (Join-Path $PSScriptRoot '../TestHelpers.ps1')

    $script:Sequencer = Join-Path $RepoDir 'src/sequencer.ps1'

    function New-CliEnv {
        # a config dir, var dir and spool for one CLI scenario
        param([string]$Name, [hashtable]$Services)
        $root = Join-Path $Work "cli-$Name"
        $cfgDir = Join-Path $root 'etc'
        New-Item -ItemType Directory -Force -Path $cfgDir | Out-Null
        $cfg = [ordered]@{
            window   = @{ open = '00:00'; close = '00:01' }   # closed nearly all day: run needs -ForceWindow
            services = $Services
        }
        Set-Content -LiteralPath (Join-Path $cfgDir 'config.json') -Value ($cfg | ConvertTo-Json -Depth 10)
        return @{ Config = $cfgDir; Var = (Join-Path $root 'var'); Spool = (Join-Path $root 'spool') }
    }

    function Invoke-Cli {
        # run the CLI with the scenario's dirs; returns @{ Out = <text>; Exit = <code> }
        param([hashtable]$CliEnv, [string[]]$CliArgs)
        $saved = @{}
        $vars = @{
            BACKUP_SEQUENCER_CONFIG_DIR = $CliEnv.Config
            BACKUP_SEQUENCER_VAR_DIR    = $CliEnv.Var
            BACKUP_SEQUENCER_SPOOL_DIR  = $CliEnv.Spool
        }
        foreach ($k in $vars.Keys) { $saved[$k] = [Environment]::GetEnvironmentVariable($k); [Environment]::SetEnvironmentVariable($k, $vars[$k]) }
        try {
            $out = & pwsh -NoProfile -NonInteractive -File $script:Sequencer @CliArgs 2>&1 | Out-String
            return @{ Out = $out; Exit = $LASTEXITCODE }
        }
        finally {
            foreach ($k in $saved.Keys) { [Environment]::SetEnvironmentVariable($k, $saved[$k]) }
        }
    }

    # recipes resolve relative to src/, so reach the test fixture from there
    $script:mockSvc = @{ enabled = $true; script = '../tests/fixtures/mock-service.ps1'; publishToReady = $true; steps = @(@{ name = 'dump'; resources = @() }) }
}

AfterAll {
    Remove-TestWork
}

Describe 'CLI with no runs yet' {
    BeforeAll {
        $script:empty = New-CliEnv -Name 'empty' -Services @{ app = $mockSvc }
    }

    It 'help prints the usage' {
        $r = Invoke-Cli $empty @('help')
        $r.Exit | Should -Be 0
        $r.Out | Should -Match 'Usage:'
        $r.Out | Should -Match 'history'
    }

    It 'status says idle when nothing was recorded' {
        $r = Invoke-Cli $empty @('status')
        $r.Out | Should -Match 'idle\s+no runs recorded yet'
    }

    It 'show fails cleanly when nothing was recorded' {
        $r = Invoke-Cli $empty @('show')
        $r.Exit | Should -Be 1
        $r.Out | Should -Match 'no runs recorded yet'
    }

    It 'plan lists a never-run service as new' {
        $r = Invoke-Cli $empty @('plan')
        $r.Exit | Should -Be 0
        $r.Out | Should -Match '(?m)^\s+\*?\s*app\s+est=\s+\?\s+overdue=new'   # unknown estimate, not 0s
    }

    It 'refuses an unexpected positional argument' {
        $r = Invoke-Cli $empty @('plan', 'oops')
        $r.Exit | Should -Be 2
        $r.Out | Should -Match "Unexpected argument\(s\) for 'plan': oops"
    }

    It 'run outside the window does nothing without -ForceWindow' {
        $r = Invoke-Cli $empty @('run')
        $r.Out | Should -Match 'Outside the backup window'
        $r = Invoke-Cli $empty @('history')
        $r.Out | Should -Match '\(nothing run\)'
    }
}

Describe 'CLI run under journald' {
    It 'prints no date line and no time column (journald stamps lines itself)' {
        $e = New-CliEnv -Name 'journal' -Services @{ app = $mockSvc }
        $saved = $env:JOURNAL_STREAM
        $env:JOURNAL_STREAM = '8:1234'
        try { $r = Invoke-Cli $e @('run', '-ForceWindow') }
        finally { $env:JOURNAL_STREAM = $saved }
        $r.Out | Should -Match '(?m)^[0-9a-f]{4}  run {17}-\s+begin'
        $r.Out | Should -Match '(?m)^[0-9a-f]{4}  app {17}-\s+end\s+ok'
        $r.Out | Should -Not -Match '(?m)^\d{4}-\d\d-\d\d -'
        $r.Out | Should -Not -Match '(?m)^[0-9a-f]{4}  \d\d:\d\d:\d\d'
    }
}

Describe 'CLI validate' {
    It 'exits 0 when every service is valid' {
        $e = New-CliEnv -Name 'valid' -Services @{ app = $mockSvc }
        $r = Invoke-Cli $e @('validate')
        $r.Exit | Should -Be 0
        $r.Out | Should -Match '(?m)^\s+app\s+OK'
    }

    It 'exits 1 and names the invalid service' {
        $bad = @{ enabled = $true; script = 'recipes/does-not-exist.ps1'; steps = @(@{ name = 'dump' }) }
        $e = New-CliEnv -Name 'invalid' -Services @{ app = $mockSvc; broken = $bad }
        $r = Invoke-Cli $e @('validate')
        $r.Exit | Should -Be 1
        $r.Out | Should -Match '(?m)^\s+broken\s+INVALID'
        $r.Out | Should -Match '(?m)^\s+app\s+OK'
    }
}

Describe 'CLI after runs' {
    BeforeAll {
        # the chatty step leaves a warning for show to report after the fact
        $chattySvc = @{ enabled = $true; script = '../tests/fixtures/mock-service.ps1'; publishToReady = $true
            steps = @(@{ name = 'dump'; resources = @() }, @{ name = 'chatty'; resources = @() }) }
        $script:ran = New-CliEnv -Name 'ran' -Services @{ app = $chattySvc }
        # two runs: the second forces past coverage so both have a service line
        $script:run1 = Invoke-Cli $ran @('run', '-ForceWindow')
        $script:run2 = Invoke-Cli $ran @('run', '-ForceWindow', '-ForceAllJobs')
        $events = @(Get-BackupEvents -EventsPath (Join-Path $ran.Var 'events.jsonl'))
        $script:runIds = @($events | Where-Object { $_.type -eq 'run.begin' } | ForEach-Object { [string]$_.runId })
    }

    It 'run -ForceWindow backs the service up' {
        $run1.Exit | Should -Be 0
        $run1.Out | Should -Match '(?m)^[0-9a-f]{4}  \d\d:\d\d:\d\d  app\s+-\s+end\s+ok\s'
        $runIds.Count | Should -Be 2
    }

    It 'history lists both runs, newest first' {
        $r = Invoke-Cli $ran @('history')
        $lines = @($r.Out -split "`n" | Where-Object { $_ -match 'ok=' })
        $lines.Count | Should -Be 2
        $lines[0] | Should -Match ([regex]::Escape($runIds[1]))
        $lines[1] | Should -Match ([regex]::Escape($runIds[0]))
    }

    It 'plan shows a measured estimate in one unit' {
        $r = Invoke-Cli $ran @('plan')
        $r.Out | Should -Match '(?m)^\s+\*?\s*app\s+est=\s+(<1|\d+)s\s+overdue='   # measured: never '?'
    }

    It 'status shows the last run when idle' {
        $r = Invoke-Cli $ran @('status')
        $r.Out | Should -Match ("idle\s+last run " + [regex]::Escape($runIds[1]))
    }

    It 'show with no argument shows the latest run' {
        $r = Invoke-Cli $ran @('show')
        $r.Exit | Should -Be 0
        $r.Out | Should -Match ("run " + [regex]::Escape($runIds[1]))
        $r.Out | Should -Not -Match ([regex]::Escape($runIds[0]))
    }

    It 'show lists the warnings of the run under the service' {
        $r = Invoke-Cli $ran @('show')
        $r.Out | Should -Match '(?m)^      ! chatty: chatty warning\s*$'
        # the second run found the first one's backup still in ready/ (no archiver here)
        $r.Out | Should -Match '(?m)^      ! replaced the previous backup in ready/'
    }

    It 'show with one reference (regression: a single ref used to throw)' {
        $r = Invoke-Cli $ran @('show', 'latest')
        $r.Exit | Should -Be 0
        $r.Out | Should -Match ("run " + [regex]::Escape($runIds[1]))
        $r.Out | Should -Match '(?m)^\s+app\s+ok'
    }

    It 'show with a unique id ending picks that run' {
        $r = Invoke-Cli $ran @('show', $runIds[0].Substring($runIds[0].Length - 4))
        $r.Exit | Should -Be 0
        $r.Out | Should -Match ("run " + [regex]::Escape($runIds[0]))
    }

    It 'show with two references shows both' {
        $r = Invoke-Cli $ran @('show', $runIds[0], $runIds[1])
        $r.Exit | Should -Be 0
        $r.Out | Should -Match ("run " + [regex]::Escape($runIds[0]))
        $r.Out | Should -Match ("run " + [regex]::Escape($runIds[1]))
    }

    It 'show with an unknown reference exits 1 and still shows the valid ones' {
        $r = Invoke-Cli $ran @('show', 'zzzz', 'latest')
        $r.Exit | Should -Be 1
        $r.Out | Should -Match "no run matches 'zzzz'"
        $r.Out | Should -Match ("run " + [regex]::Escape($runIds[1]))
    }
}

Describe 'CLI trash' {
    BeforeEach {
        $script:tr = New-CliEnv -Name ("trash-" + [guid]::NewGuid().ToString('n').Substring(0, 6)) -Services @{}
        $script:trashDir = Join-Path $tr.Spool 'trash'
        New-Item -ItemType Directory -Force -Path (Join-Path $trashDir 'forgejo-0123456789ab'), (Join-Path $trashDir 'junk'), $tr.Var | Out-Null
        Set-Content -LiteralPath (Join-Path $trashDir 'forgejo-0123456789ab/a.bin') -Value ('a' * 5000)
        $script:evPath = Join-Path $tr.Var 'events.jsonl'
        Set-Content -LiteralPath $evPath -Value '{"ts":"2026-11-18T13:00:00Z","type":"trash.move","runId":"20261118-130000-a558","svc":"forgejo","reason":"local-copy-dropped","trashName":"forgejo-0123456789ab","status":"ok"}'
    }

    It 'lists what the trash holds, with where it came from' {
        $r = Invoke-Cli $tr @('trash')
        $r.Exit | Should -Be 0
        $r.Out | Should -Match '2 items, 5 KB'
        $r.Out | Should -Match '(?m)^  forgejo-0123456789ab\s+5 KB\s+1 files  forgejo\s+local-copy-dropped\s+run a558  moved 2026-11-18T'
        $r.Out | Should -Match '(?m)^  junk\s+0 KB\s+0 files  no record'
        (Test-Path (Join-Path $trashDir 'junk')) | Should -BeTrue   # listing deletes nothing
    }

    It 'deletes only the items named, logged as by command' {
        $r = Invoke-Cli $tr @('trash', '-Delete', 'junk')
        $r.Exit | Should -Be 0
        $r.Out | Should -Match '(?m)^----  \d\d:\d\d:\d\d  run\s+\[delete\]\s+done\s+ok .*no record: junk'
        $r.Out | Should -Match 'freed 0 KB \(1 item\)'
        (Test-Path (Join-Path $trashDir 'junk')) | Should -BeFalse
        (Test-Path (Join-Path $trashDir 'forgejo-0123456789ab')) | Should -BeTrue
        $del = @(Get-BackupEvents -EventsPath $evPath | Where-Object { $_.type -eq 'trash.delete' })
        $del.Count | Should -Be 1
        $del[0].by | Should -Be 'command'
        Test-HasProp $del[0] 'runId' | Should -BeFalse
    }

    It 'deletes everything when no name is given, and lists the deletions after' {
        (Invoke-Cli $tr @('trash', '-Delete')).Exit | Should -Be 0
        @(Get-ChildItem -LiteralPath $trashDir).Count | Should -Be 0
        $r = Invoke-Cli $tr @('trash')
        $r.Out | Should -Match '0 items'
        $r.Out | Should -Match '(?m)^  \S+  by command\s+5 KB  forgejo-0123456789ab$'
    }

    It 'names an unknown item and exits 1' {
        $r = Invoke-Cli $tr @('trash', '-Delete', 'nope')
        $r.Exit | Should -Be 1
        $r.Out | Should -Match 'not in trash: nope'
        @(Get-ChildItem -LiteralPath $trashDir).Count | Should -Be 2
    }

    It 'refuses to delete while a run holds the lock' {
        Set-Content -LiteralPath (Join-Path $tr.Var 'sequencer.lock') -Value $PID   # a live process
        $r = Invoke-Cli $tr @('trash', '-Delete')
        $r.Exit | Should -Be 1
        $r.Out | Should -Match 'a run is in progress'
        @(Get-ChildItem -LiteralPath $trashDir).Count | Should -Be 2
        (Test-Path (Join-Path $tr.Var 'sequencer.lock')) | Should -BeTrue   # not taken from the run
    }

    It 'keeps an item it cannot delete and exits 1' -Skip:($IsWindows) {
        $stuck = Join-Path $trashDir 'stuck'
        New-Item -ItemType Directory -Force -Path $stuck | Out-Null
        Set-Content -LiteralPath (Join-Path $stuck 'f.bin') -Value 'z'
        & chmod 555 $stuck
        try {
            $r = Invoke-Cli $tr @('trash', '-Delete', 'stuck')
            $r.Exit | Should -Be 1
            $r.Out | Should -Match '(?m)\[delete\]\s+done\s+FAIL .*! stuck: .*; kept\s*$'
            (Test-Path $stuck) | Should -BeTrue
            (Get-BackupEvents -EventsPath $evPath | Where-Object { $_.type -eq 'trash.delete' }).status | Should -Be 'fail'
            (Test-Path (Join-Path $tr.Var 'sequencer.lock')) | Should -BeFalse   # released
        }
        finally { & chmod 755 $stuck }
    }
}
